import{_ as s,o as a,c as o,a4 as t}from"./chunks/framework.B-wJupoK.js";const n="/assets/devecocli-arch.CfE493mm.png",d="/assets/usage-compare.DBK-xGlN.png",i="/assets/image-20260707225508766.DPR2-UH2.png",c="/assets/image-20260707225549751.CzVw3AaT.png",l="/assets/quickstart-flow.5dDj-Wp-.png",r="/assets/image-20260707230055269.CwteMv7-.png",p="/assets/image-20260707233354554.CmRE3Mf1.png",h="/assets/image-20260707233739674.CJ9-lOjs.png",m="/assets/image-20260707233835978.C0u984FE.png",u="/assets/image-20260707234321899.IZB_nArR.png",v="/assets/image-20260707234802309.BQOse9Go.png",k="/assets/image-20260708000004502.PyIbbRFt.png",g="/assets/image-20260708000246819.Am5iQA8o.png",b="/assets/image-20260708003702179.B37-KMV7.png",S=JSON.parse('{"title":"手把手带你上手鸿蒙应用开发利器 DevEcoCli","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/手把手带你上手鸿蒙应用开发利器 DevEcoCli和DevEcoCode/01-手把手带你上手鸿蒙应用开发利器 DevEcoCli/手把手带你上手鸿蒙应用开发利器 DevEcoCli.md","filePath":"鸿蒙开发技巧/手把手带你上手鸿蒙应用开发利器 DevEcoCli和DevEcoCode/01-手把手带你上手鸿蒙应用开发利器 DevEcoCli/手把手带你上手鸿蒙应用开发利器 DevEcoCli.md","lastUpdated":1784253000000,"__rawMarkdown":"# 手把手带你上手鸿蒙应用开发利器 DevEcoCli\\n\\n## 前言\\n\\n上周（7 月 2 号）我在 51CTO 平台上做了一场关于鸿蒙应用开发工具 **DevEcoCli** 和 **DevEcoCode** 的直播，直播反响不错，同时也有不少开发者提出了一些疑问。其中比较典型的是：\\n\\n- 如何快速上手使用 DevEcoCli？\\n- 如何让自己的 AI 工具与 DevEcoCli 结合来提效？\\n\\n所以这篇文章就来专门分享 **鸿蒙应用开发利器 DevEcoCli**。\\n\\n## DevEcoCli 介绍\\n\\n**一个面向 HarmonyOS 应用开发的统一命令行入口。**\\n\\n`DevEcoCli` 将 `DevEco Studio` 工具链统一封装为一个 `CLI`，内置 `ohpm`、`hvigor`、`hdc`、`emulator`、`hilog`，同时集成 HarmonyOS 技能安装、项目脚手架、本地 HarmonyOS 文档检索和 `MCP` 服务。\\n\\n> - **CLI**：Command-Line Interface 命令行接口，通过文字命令与程序交互的方式。\\n> - **ohpm**：Open Harmony Package Manager，鸿蒙包管理工具，类似 npm，用于安装管理 ArkTS/ArkUI 三方库。\\n> - **hvigor**：DevEco Studio 的构建工具链，类似 Gradle，负责编译、打包、执行构建任务。\\n> - **hdc**：HarmonyOS Device Connector，鸿蒙设备连接工具，类似 Android 的 adb，用于和真机/模拟器通信（安装应用、推送文件、抓日志等）。\\n> - **emulator**：模拟器，在本地电脑上模拟鸿蒙设备的运行环境。\\n> - **hilog**：鸿蒙系统的日志工具，用于输出和查看应用运行日志。\\n> - **MCP**：Model Context Protocol 模型上下文协议，一种让 AI 模型与外部工具/服务交互的标准协议，这里指 `deveco-mcp` 语法检查服务。\\n\\n通俗地理解：**DevEcoCli 直接集成了 DevEco Studio 中大部分的功能和能力**，从而更加方便地在 AI 工具中调用 DevEco Studio 的能力。\\n\\n![DevEcoCli 能力全景图](assets/devecocli-arch.png)\\n\\n## DevEcoCli 使用方式\\n\\n一般有两种使用方式：\\n\\n1. **手动输入命令**：开发者自己记忆 DevEcoCli 的相关命令，手动在终端中输入使用。需要注意的是，**命令记错或输入错误时将得不到正确的效果**，所以一般建议使用第二种方式。\\n\\n2. **结合 AI 工具**：把 DevEcoCli 集成到你的 AI 工具中。不管你使用的是 Trae、Codex、Qoder、Claude Code 还是 CodeBuddy 等 AI 工具，都可以和 DevEcoCli 进行无缝集成。\\n\\n![两种使用方式对比](assets/usage-compare.png)\\n\\n## DevEcoCli 快速上手\\n\\n### 环境要求\\n\\n- 操作系统为 `macOS` 或 `Windows`，**目前不支持 Linux 和鸿蒙 PC**，这一点需要特别注意。\\n- **Node.js >= 18**，推荐使用 22 及以上版本。\\n\\n  > 下载地址：https://nodejs.org/en\\n\\n  ![](assets/image-20260707225508766.png)\\n\\n- **DevEco Studio >= 6.1.0**\\n\\n  > 下载地址：https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-tools-overview\\n\\n  ![](assets/image-20260707225549751.png)\\n\\n  - **macOS**：必须安装在 `~/Applications` 或 `/Applications` 目录下。\\n\\n![DevEcoCli 快速上手流程](assets/quickstart-flow.png)\\n\\n### 安装 DevEcoCli\\n\\n确认上述环境准备无误后，可以执行以下命令安装 DevEcoCli：\\n\\n```bash\\nnpm install -g @deveco/deveco-cli@latest\\n```\\n\\n安装成功后，在终端中输入 `devecocli -v` 查看版本。\\n\\n![](assets/image-20260707230055269.png)\\n\\n至此表示 DevEcoCli 安装成功。\\n\\n## 常用指令说明\\n\\n这里罗列一下实际开发中常用的指令。\\n\\n```text\\nHarmonyOS 应用开发命令行工具\\n\\nOptions:\\n  -V, --version          output the version number\\n  -h, --help             display help for command\\n\\nCommands:\\n  build [options]        构建 HarmonyOS 项目\\n  run [options]          构建并在连接的设备上运行项目\\n  update                 将 deveco-cli 更新至最新版本\\n  device                 管理已连接的设备\\n  emulator               管理模拟器实例\\n  skills                 管理 HarmonyOS 技能（skills）\\n  log [options]          获取设备应用日志\\n  create [options]       脚手架方式创建新的 HarmonyOS 应用项目\\n  init [options]         将 deveco-cli skill 安装到 AI 代理中，或将 deveco-mcp 服务器配置进 AI 代理\\n  serve                  托管内置的辅助协议服务器\\n  docs [options]         从本地文档目录搜索并阅读 HarmonyOS 文档\\n  help [command]         显示指定命令的帮助信息\\n```\\n\\n基本示例如下。\\n\\n### 创建工程\\n\\n在当前目录创建一个名为 `MyApp` 的鸿蒙工程（默认 API 23）：\\n\\n```bash\\ndevecocli create --app-name MyApp\\n```\\n\\n完整命令如下：\\n\\n```bash\\ndevecocli create --app-name <name> --project-path <path> --bundle-name <bundle> --api-level <level>\\n```\\n\\n**参数说明：**\\n\\n| 参数名         | 说明                                                                                   |\\n| -------------- | -------------------------------------------------------------------------------------- |\\n| `--app-name`   | 必选，应用名称                                                                         |\\n| `--project-path` | 可选，工程路径，默认为：`./<appname>`                                                |\\n| `--bundle-name`  | 可选，包名，默认为：`com.example.<appname>`，`appname` 会自动转为小写               |\\n| `--api-level`    | 可选，API 级别，最小值为 17，最大值从安装的 `DevEco Studio` 的 `HarmonyOS SDK` 中自动获取 |\\n\\n### 模拟器\\n\\n在启动模拟器之前需要先下载好对应的模拟器，可以先查看已有的模拟器：\\n\\n```bash\\ndevecocli emulator list\\n```\\n\\n![](assets/image-20260707233354554.png)\\n\\n可以看到这里有 **Pura 90**，然后启动它：\\n\\n```bash\\ndevecocli emulator start \\"Pura 90\\"\\n```\\n\\n![](assets/image-20260707233739674.png)\\n\\n![](assets/image-20260707233835978.png)\\n\\n### 运行到模拟器上\\n\\n这个时候可以将刚刚创建的工程运行到模拟器上，运行命令如下：\\n\\n```bash\\ndevecocli run\\n```\\n\\n![](assets/image-20260707234321899.png)\\n\\n### 查询本地文档\\n\\n在实际开发时，往往需要参考已有的 API 文档进行开发，这个能力也集成到 DevEcoCli 中了。比如查询 **Button** 资料：\\n\\n> 需要注意的是，这个查询其实并不是直接给开发者看的，而是为了后面结合 AI 工具使用，让 AI 工具更加准确地获取信息。\\n\\n```bash\\ndevecocli docs search Button\\n```\\n\\n![](assets/image-20260707234802309.png)\\n\\n### 查询 Skill\\n\\n鸿蒙官方做了一个**格物市场**，上面提供了一些可复用的能力，比如 Skill 和 MCP 等。\\n\\n> https://matrix.openharmony.cn/#/skillSquare\\n\\n![](assets/image-20260708000004502.png)\\n\\n开发者可以打开上面的网址进行了解使用，也可以使用 DevEcoCli 直接查询并下载使用这些 Skill：\\n\\n```bash\\ndevecocli skills list --long\\n```\\n\\n**参数说明：**\\n\\n| 参数名       | 说明                                                                       |\\n| ------------ | -------------------------------------------------------------------------- |\\n| `-l, --long` | 可选，显示 `Skill` 详情，包括描述和已安装的智能体列表。缺省时，仅显示 `Skill` 名称 |\\n\\n![](assets/image-20260708000246819.png)\\n\\n也可以根据关键字进行查询：\\n\\n```bash\\ndevecocli skills find <keyword>\\n```\\n\\n还可以把 Skill 添加到你的 AI 工具（智能体）上。具体的添加命令比较繁琐，这里就不细讲了——**当你的智能体集成了 DevEcoCli 之后，直接用自然语言对话即可**。\\n\\n## 集成到 AI 工具（智能体）\\n\\n上面是对 DevEcoCli 基本使用的讲解，但**结合常用的 AI 工具才是发挥它最大优势的做法**。\\n\\nDevEcoCli 内置了对 `trae-cn`、`opencode`、`cursor`、`codebuddy`、`qoder`、`claude-code`、`codex` 的支持。这个\\"支持\\"的意思是：可以把 DevEcoCli 直接当成一个 Skill 集成到上述智能体上，方便直接调用。\\n\\n```bash\\n# 把 deveco-cli 技能装给 opencode（用户级）\\ndevecocli init --agent opencode\\n\\n# 装给多个\\ndevecocli init --agent opencode,cursor,atomcode\\n\\n# 装到某个项目目录下\\ndevecocli init --agent cursor --project ./MyApp\\n\\n# 配置 MCP 服务（语法检查）给指定智能体\\ndevecocli init --mcp --agent opencode --project ./MyApp\\n\\n# 覆盖已有配置\\ndevecocli init --agent cursor --force\\n```\\n\\n## 智能体中使用 DevEcoCli\\n\\n上一步已经把 DevEcoCli 作为一个 Skill 添加给了我们的智能体。以 **Claude Code** 为例，后期启动 Claude Code 时，便可以直接使用：\\n\\n```text\\n/deveco-cli  xxxxxx\\n```\\n\\n![](assets/image-20260708003702179.png)\\n\\n## 命令总览表\\n\\n| 功能分类   | 顶级命令   | 子命令                    | 用途说明                                              | 关键参数                                                     | 典型示例                                                     |\\n| ---------- | ---------- | ------------------------- | ----------------------------------------------------- | ------------------------------------------------------------ | ------------------------------------------------------------ |\\n| 项目脚手架 | `create`   | —                         | 创建新的 HarmonyOS 应用工程（Empty Ability 模板）       | `--app-name`(必选)、`--project-path`、`--bundle-name`、`--api-level` | `devecocli create --app-name MyApp`                          |\\n| 构建打包   | `build`    | (默认)                    | 编译并打包工程，产出 `.hap` / `.hsp` / `.har` / `.app` | `--product`、`--modules`、`--build-mode`                     | `devecocli build --build-mode release`                       |\\n| 构建打包   | `build`    | `build clean`             | 清理项目的构建产物                                    | —                                                            | `devecocli build clean`                                      |\\n| 构建打包   | `run`      | —                         | 构建后安装到真机/模拟器并启动                         | `--module`、`--device`、`--product`、`--build-mode`、`--ability`、`--uninstall`、`--skip-build` | `devecocli run --device 127.0.0.1:5555`                      |\\n| 设备管理   | `device`   | `device list`             | 查询所有已连接的设备（真机 + 运行中模拟器）            | —                                                            | `devecocli device list`                                      |\\n| 设备管理   | `device`   | `device view`             | 查看设备序列号、名称、类型、OS 版本等详情             | `-t, --target <name\\\\|serial>`                                | `devecocli device view`                                      |\\n| 模拟器     | `emulator` | `emulator list`           | 查看本地模拟器实例                                    | —                                                            | `devecocli emulator list`                                    |\\n| 模拟器     | `emulator` | `emulator start`          | 启动模拟器（仅 release 版本）                         | `[names...]`(必选)                                           | `devecocli emulator start Phone`                             |\\n| 模拟器     | `emulator` | `emulator stop`           | 关闭模拟器                                            | `[names...]`(必选)                                           | `devecocli emulator stop Phone`                              |\\n| 模拟器     | `emulator` | `emulator create`         | 创建模拟器                                            | `name`、`--device-type`、`--os-version`、`--force`           | `devecocli emulator create MyPhone --device-type phone --os-version \\"HarmonyOS 6.0.1(21)\\"` |\\n| 模拟器     | `emulator` | `emulator delete`         | 删除模拟器                                            | `name`                                                       | `devecocli emulator delete MyPhone`                          |\\n| 模拟器     | `emulator` | `emulator image list`     | 查询模拟器镜像列表                                    | `--device-type`、`--all`、`--format`                         | `devecocli emulator image list`                              |\\n| 模拟器     | `emulator` | `emulator image download` | 下载模拟器镜像（仅 release 版本）                     | `--device-type`、`--os-version`、`--force`                   | `devecocli emulator image download --device-type phone --os-version \\"HarmonyOS 6.0.1(21)\\"` |\\n| 模拟器     | `emulator` | `emulator image remove`   | 删除模拟器镜像                                        | `--device-type`、`--os-version`                              | `devecocli emulator image remove --device-type phone --os-version \\"HarmonyOS 6.0.1(21)\\"` |\\n| 模拟器     | `emulator` | `emulator license view`   | 查看许可协议（只读）                                  | —                                                            | `devecocli emulator license view`                            |\\n| 模拟器     | `emulator` | `emulator license accept` | 查看并接受许可协议                                    | —                                                            | `devecocli emulator license accept`                          |\\n| 日志调试   | `log`      | —                         | 获取设备 `hilog` 日志或崩溃日志                       | `--device`、`--crash`、`--level`、`--bundle-name`、`--keyword`、`--tail`、`--from`、`--to`、`--follow` | `devecocli log --level E`                                    |\\n| 文档检索   | `docs`     | `docs search`             | 关键词搜索版本说明、指南、API、最佳实践、FAQ 等       | `keywords...`、`--catalog`、`--format`、`--limit`            | `devecocli docs search List`                                 |\\n| 文档检索   | `docs`     | `docs read`               | 按文档 ID 读取文档完整内容                            | `documentId`                                                 | `devecocli docs read <documentId>`                           |\\n| 文档检索   | `docs`     | `docs catalog`            | 查询文档分类与分类名称                                | `--format`                                                   | `devecocli docs catalog`                                     |\\n| AI 集成    | `init`     | —                         | 将内置技能或 MCP 服务配置到智能体                     | `--agent`、`--project`、`--path`、`--skill`、`--mcp`、`-f, --force` | `devecocli init --agent cursor`                              |\\n| AI 集成    | `skills`   | `skills list`             | 列出可用的技能                                        | `-l, --long`                                                 | `devecocli skills list`                                      |\\n| AI 集成    | `skills`   | `skills find`             | 按关键词搜索技能                                      | `<keyword>`                                                  | `devecocli skills find deveco`                               |\\n| AI 集成    | `skills`   | `skills add`              | 将技能添加到智能体                                    | `--all` / `--skill`、`--agent`、`--project`、`--path`、`-f, --force` | `devecocli skills add --skill <name> --agent cursor`         |\\n| AI 集成    | `skills`   | `skills remove`           | 从智能体中删除已添加的技能                            | `--skill`(必选)、`--agent`、`--project`、`--path`            | `devecocli skills remove --skill <name>`                     |\\n| AI 集成    | `serve`    | `serve mcp`               | 启动本地 MCP 服务（供智能体调用 ArkTS/C++ 语法检查）   | —                                                            | `devecocli serve mcp`                                        |\\n| 自身管理   | `update`   | —                         | 更新 `deveco-cli` 到最新版本                          | —                                                            | `devecocli update`                                           |\\n\\n## 总结\\n\\n这篇文章带大家从 0 到 1 上手了 DevEcoCli，核心脉络可以归纳为以下四点：\\n\\n1. **是什么**：DevEcoCli 把 DevEco Studio 的能力（`ohpm`、`hvigor`、`hdc`、`hilog`、模拟器等）统一封装成一个**命令行入口**，是专门为 AI 时代的鸿蒙开发而设计的。\\n2. **怎么用**：有手动输入命令和结合 AI 工具两种方式，**强烈推荐后者**——把 DevEcoCli 当作一个 Skill 集成进智能体，用自然语言驱动，省去死记命令的负担。\\n3. **上手五步**：装环境（Node.js / DevEco Studio）→ 装 CLI → 建工程（`create`）→ 启动模拟器（`emulator`）→ 跑起来（`run`）。\\n4. **进阶提效**：用 `docs` 让 AI 精准检索本地文档、用 `skills` 复用格物市场的能力、用 `init` 一键集成进 Claude Code / Cursor 等智能体。\\n\\n一句话概括：**DevEcoCli 让鸿蒙应用开发从\\"点点点\\"变成\\"一句话\\"**，再配合 AI 工具，能显著提升开发效率。如果看完还有疑问，欢迎在评论区交流。\\n\\n## 参考文献\\n\\n\\n\\n1. Node.js 官方网站 ：https://nodejs.org/en\\n2. DevEco Studio 工具概览：https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-tools-overview\\n3. 格物市场 · 技能广场：https://matrix.openharmony.cn/#/skillSquare\\n4. @deveco/deveco-cli · npm：https://www.npmjs.com/package/@deveco/deveco-cli\\n5. HarmonyOS 7新特性：https://developer.huawei.com/consumer/cn/features/?ha_source=51cto&ha_sourceId=70000008\\n6. HarmonyOS AI开发提效工具：DevEco Code & DevEco CLI：https://developer.huawei.com/consumer/cn/forum/topic/0202216647056043902?ha_source=51cto&ha_sourceId=70000008\\n7. 社区干货合集：一帖看全，高效查阅\\n   https://developer.huawei.com/consumer/cn/forum/topic/0201215860119833282?ha_source=51cto&ha_sourceId=70000008\\n"}'),C={name:"鸿蒙开发技巧/手把手带你上手鸿蒙应用开发利器 DevEcoCli和DevEcoCode/01-手把手带你上手鸿蒙应用开发利器 DevEcoCli/手把手带你上手鸿蒙应用开发利器 DevEcoCli.md"};function y(F,e,E,D,A,_){return a(),o("div",null,[...e[0]||(e[0]=[t("",81)])])}const I=s(C,[["render",y]]);export{S as __pageData,I as default};
